import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);  // Armazena todos os clientes
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);  // Carregando dados

  useEffect(() => {
    // Carregar a lista de clientes ao montar o componente
    const fetchClientes = async () => {
      try {
        const response = await axios.get('http://localhost:8080/clientes');  // Busca todos os clientes
        setClientes(response.data);  // Atualiza o estado com a lista de clientes
      } catch (error) {
        console.error('Erro ao carregar clientes:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchClientes();  // Chama a função para carregar os clientes
  }, []);

  // Filtra os clientes com base no termo de busca
  const handleSearch = () => {
    if (searchTerm) {
      const filteredClientes = clientes.filter(cliente =>
        cliente.nome.toLowerCase().includes(searchTerm.toLowerCase())
      );
      return filteredClientes;
    }
    return clientes;  // Retorna todos os clientes se não houver busca
  };

  return (
    <div className="cliente-list">
      <h2>Lista de Clientes</h2>

      {/* Campo de busca */}
      <input
        type="text"
        placeholder="Buscar por nome..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}  // Atualiza o estado de busca
      />
      <button onClick={handleSearch}>Buscar</button>

      {/* Se estiver carregando, exibe uma mensagem de loading */}
      {isLoading ? (
        <p>Carregando...</p>
      ) : (
        <ul>
          {handleSearch().length === 0 ? (
            <li>Nenhum cliente encontrado.</li>
          ) : (
            handleSearch().map(cliente => (
              <li key={cliente.id}>
                {cliente.nome} - {cliente.email} - {cliente.telefone}
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  );
};

export default ClienteList;
